        assertThatThrownBy(() -> service.calcular(request))
                .isInstanceOf(ErroPedidoException.class)
                .extracting(e -> ((ErroPedidoException) e).getCodigo())
                .isEqualTo("MODALIDADE_INDISPONIVEL");
    }

